-- Garrison construction sites: laborers appear and work on the scaffolding of the remaining small, medium and large plots of both garrisons while a building is being built

DELETE FROM `garrison_building_creature` WHERE `BuildID` = 0 AND `building` = 1 AND (`plotID`, `map`) IN ((18, 1159), (19, 1159), (20, 1159), (23, 1159), (24, 1159), (25, 1159), (20, 1153), (24, 1153), (25, 1153));

